import {ssrRenderMode} from '../../framework-comparison/src/ssr-render-mode.mjs';
import {readFile,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {installDevelopmentProcessLifecycle} from '../../scripts/development-process-lifecycle.mjs';
import {startSsrLoadProcess} from '../../framework-comparison/src/ssr-load-process-owner.mjs';
import {startSsrWorker,stopSsrWorker,controlSsrWorker} from '../../framework-comparison/src/ssr-worker-controller.mjs';
import {availableSsrRuntimes,measureSsrArtifact,ssrEnvironmentMetadata} from '../../framework-comparison/src/ssr-run-environment.mjs';
const plan=JSON.parse(await readFile(process.argv[2],'utf8')),output=process.argv[3];
const renderMode=ssrRenderMode();
const runtimeId=process.argv[4]; if(!['node','bun'].includes(runtimeId))throw Error('Invalid runtime'); const runtimes=availableSsrRuntimes('node,bun');
const artifacts={}; const identities={};
for(const id of ['exact','react']){
 const path=resolve(`framework-comparison/participants/${id}/${runtimeId==='bun'?'dist-bun-server/bun-server-entry.js':'dist-server/server-entry.js'}`);
 const bytes=await readFile(path);artifacts[id]={path,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')};

}
artifacts.server=await measureSsrArtifact(resolve('packages/server/dist'));
artifacts[runtimeId==='bun'?'bunAdapter':'nodeAdapter']=await measureSsrArtifact(resolve(`framework-adapters/${runtimeId==='bun'?'bun':'node'}-adapter/dist`));
const prior={artifacts,environment:ssrEnvironmentMetadata(runtimes)};
const report={kind:'multi-driver-preloaded-ssr',complete:false,runtimeId,renderMode,transports:{exact:runtimeId==='bun'?'bun-fetch':'node-http',react:runtimeId==='bun'?'bun-fetch':'node-http'},createdAt:new Date().toISOString(),plan,artifacts:prior.artifacts,environment:prior.environment,blocks:[],runner:await readFile(import.meta.filename,'utf8')};
report.telemetryControl={transport:'persistent-http',source:'framework-comparison/src/ssr-worker-controller.mjs',sha256:createHash('sha256').update(await readFile(resolve('framework-comparison/src/ssr-worker-controller.mjs'))).digest('hex')};
const runtime=availableSsrRuntimes(runtimeId)[0];let service,worker,drivers=[],timer,polling;
async function close(){clearInterval(timer);const ds=drivers;drivers=[];const closed=await Promise.allSettled(ds.map(d=>d.close()));await polling;if(worker){const w=worker;worker=undefined;await stopSsrWorker(w);}if(service){const s=service;service=undefined;await s.close();}const failures=closed.filter(x=>x.status==='rejected');if(failures.length)throw new AggregateError(failures.map(x=>x.reason));}
async function verify(){for(const id of ['exact','react']){const a=report.artifacts[id];assert.equal(createHash('sha256').update(await readFile(a.path)).digest('hex'),a.sha256);}}
const lifecycle=installDevelopmentProcessLifecycle({label:'Multi-driver preloaded SSR',close});
try{await verify();for(let population=0;population<2;population++)for(const id of population?['react','exact']:['exact','react']){
 const serviceIntervals=[],telemetry=[],telemetryErrors=[];
 service=await startSsrLoadProcess('service',{onInterval:r=>serviceIntervals.push(r)});
 worker=await startSsrWorker({runtime,participantId:id,transport:runtimeId==='bun'?'bun-fetch':'node-http',workerPath:resolve('framework-comparison/src/ssr-benchmark-worker.mjs'),workingDirectory:resolve('framework-comparison'),serviceUrl:service.url,environment:{COMPARISON_SSR_BOUNDED_TELEMETRY:'1',...(id==='exact'?{COMPARISON_EXACT_SERVER_ENTRY:report.artifacts.exact.path}:{})}});
 assert.equal(worker.renderMode, renderMode);
 const response=await fetch(worker.url+(plan.preloaded===false?'':'?__benchmarkPreloaded=true')); assert.equal(response.status,200); const body=Buffer.from(await response.arrayBuffer()); assert.ok(body.toString().includes('Delayed fulfillment events')); identities[id]={bytes:body.length,hash:createHash('sha256').update(body).digest('hex')};
 await controlSsrWorker(worker,'reset');
 telemetry.push({epochMs:Date.now(),value:await controlSsrWorker(worker,'telemetry')});
 timer=setInterval(()=>{if(polling)return;polling=controlSsrWorker(worker,'telemetry').then(value=>telemetry.push({epochMs:Date.now(),value}),e=>telemetryErrors.push(e.message)).finally(()=>{polling=undefined;});},1000);
 for(let i=0;i<plan.drivers;i++)drivers.push(await startSsrLoadProcess('driver'));
 console.log('Population',population+1,id,'drivers',drivers.length);
 for(const d of drivers)d.run({url:worker.url+(plan.preloaded===false?'':'?__benchmarkPreloaded=true'),contains:'Delayed fulfillment events',expectedIdentity:identities[id],maxInFlight:256,maxLagMs:50,timeoutMs:10000,stages:plan.stages});
 const results=await Promise.race([Promise.all(drivers.map(d=>d.result)),service.result]);
 for(const r of results)for(const s of r.stages){assert.equal(s.offered,s.started+s.missedLag+s.missedCapacity+s.missedDeadline);assert.equal(s.completed,s.valid+s.errors);assert.equal(s.started,s.completed);}
 clearInterval(timer);await polling;telemetry.push({epochMs:Date.now(),value:await controlSsrWorker(worker,'telemetry')});
 const block={population,id,workerPid:worker.child.pid,workerStderr:worker.stderr(),servicePid:service.pid,results,telemetry,telemetryErrors,serviceIntervals};report.blocks.push(block);
 for(let i=0;i<plan.stages.length;i++){const ss=results.map(r=>r.stages[i]);console.log(ss[0].name,JSON.stringify({rps:ss.reduce((n,s)=>n+s.validRps,0),errors:ss.reduce((n,s)=>n+s.errors,0),misses:ss.reduce((n,s)=>n+s.missedCapacity+s.missedLag+s.missedDeadline,0)}));}
 await close();await writeFile(output,JSON.stringify(report));
 }await verify();assert.deepEqual(await measureSsrArtifact(resolve('packages/server/dist')),artifacts.server);assert.deepEqual(await measureSsrArtifact(resolve(`framework-adapters/${runtimeId==='bun'?'bun':'node'}-adapter/dist`)),artifacts[runtimeId==='bun'?'bunAdapter':'nodeAdapter']);report.complete=true;await writeFile(output,JSON.stringify(report));
}finally{await close();lifecycle.dispose();}

runners.publish:
import {execFileSync} from 'node:child_process';
import assert from 'node:assert/strict';
import {readFile,writeFile,copyFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {measureSsrArtifact} from '../../framework-comparison/src/ssr-run-environment.mjs';
import {createSsrCapacityReport} from '../../framework-comparison/src/publish-ssr-capacity.mjs';
import {refreshDocsSsrDiagnostics,refreshDocsBunSsrDiagnostics} from '../../scripts/component-local-target-abi/refresh-docs-ssr-report.mjs';
const root='.tmp/ssr-fresh',prefix='docs/performance-baselines/ssr-fresh-2026-09-12';
const json=async path=>JSON.parse(await readFile(path,'utf8'));
const sourceState=await json(root+'/source-state.json');
const commit=sourceState.baseCommit;
const sourceSha256=createHash('sha256').update(JSON.stringify(sourceState.files)).digest('hex');
for(const [path,hash] of Object.entries(sourceState.files)) {
 if(path.startsWith('apps/docs/') || path.startsWith('docs/') || path.endsWith('README.md')) continue;
 assert.equal(createHash('sha256').update(await readFile(path)).digest('hex'),hash,path+' changed since measurement');
}

const execution=await json(root+'/execution.json');
const stages=Object.values(Object.fromEntries(execution.map(s=>[s.name,s])));
assert.equal(stages.length,20);assert.ok(stages.every(s=>s.code===0));
const sources={},captures={};
for(const mode of ['string','stream'])for(const runtime of ['node','bun'])for(const lane of ['multi','normal','arrivals']){
 const name=runtime+(mode==='stream'?'-stream':'')+'-'+lane;
 const raw=await json(root+'/'+name+'.json');assert.equal(raw.complete,true);assert.equal(raw.renderMode,mode);
 const adapter=await measureSsrArtifact('framework-adapters/'+runtime+'-adapter/dist');
 assert.deepEqual(raw.artifacts[runtime==='bun'?'bunAdapter':'nodeAdapter'],adapter);
 captures[name]=raw;
}
for(const name of [...Object.keys(captures),'ssr','ssr-stream','node-prepared','bun-prepared','node-stream-prepared','bun-stream-prepared']){
 const path=prefix+'-'+name+'.json';await copyFile(root+'/'+name+'.json',path);
 sources[name]={path,sha256:createHash('sha256').update(await readFile(path)).digest('hex')};
}
const previous=await json(root+'/before-performance-report.json');
const ssr=await json(root+'/ssr.json'),stream=await json(root+'/ssr-stream.json');
assert.equal(ssr.harness.renderMode,'string');assert.equal(stream.harness.renderMode,'stream');
for(const raw of [ssr,stream]){assert.equal(raw.complete,true);assert.equal(raw.publishable,true);}
const report=refreshDocsBunSsrDiagnostics(refreshDocsSsrDiagnostics(previous,ssr),ssr);
report.metadata.createdAt=new Date().toISOString();report.metadata.capture='ssr-fresh-2026-09-12';
report.metadata.ssrCommit=commit;report.metadata.ssrSourceSha256=sourceSha256;report.metadata.ssrCapture='ssr-fresh-2026-09-12';
report.metadata.sources={...previous.metadata.sources,ssrDiagnostics:sources.ssr,ssrBunDiagnostics:sources.ssr};
assert.deepEqual(report.browserCharts,previous.browserCharts);
const streamReport=refreshDocsBunSsrDiagnostics(refreshDocsSsrDiagnostics(previous,stream),stream);
streamReport.metadata={renderMode:'stream',ssrCommit:commit,ssrSourceSha256:sourceSha256,createdAt:stream.createdAt,ssrCreatedAt:stream.createdAt,ssrDiagnosticsEnvironment:stream.environment,ssrSequentialSamples:stream.harness.sampleCount,ssrBurstSamples:stream.harness.concurrencyWaves,ssrRetentionCheckpoints:stream.harness.retentionBatches,source:sources['ssr-stream']};
streamReport.server.sequential.comment='Complete warm HTTP response latency using the streaming API, including fixture fetching, rendering, and stream consumption. Lower is better.';
streamReport.server.bun.sequential.comment=streamReport.server.sequential.comment;
await writeFile('apps/docs/src/data/performance-report.json',JSON.stringify(report,null,2)+'\n');
await writeFile(root+'/report-data.json',JSON.stringify(report,null,2)+'\n');
await writeFile('apps/docs/src/data/ssr-stream-report.json',JSON.stringify({metadata:streamReport.metadata,server:streamReport.server},null,2)+'\n');
const capacities={};
for(const mode of ['string','stream'])for(const runtime of ['node','bun']){
 const suffix=mode==='stream'?'-stream':'';
 const lanes=Object.fromEntries(['multi','normal','arrivals'].map(l=>[l,captures[runtime+suffix+'-'+l]]));
 const capacity=createSsrCapacityReport(lanes,lanes.normal);capacities[runtime+suffix]=capacity;
 const name=mode==='stream'?'ssr-'+runtime+'-stream-capacity-report':'ssr-'+(runtime==='bun'?'bun-':'')+'capacity-report';
 await writeFile('apps/docs/src/data/'+name+'.json',JSON.stringify(capacity,null,2)+'\n');
}
const log=await readFile(root+'/server.log','utf8');
const server=JSON.parse(log.split(/\r?\n/).find(s=>s.startsWith('EXACT_SERVER_BENCHMARK_JSON=')).slice('EXACT_SERVER_BENCHMARK_JSON='.length));
await writeFile(prefix+'-server.json',JSON.stringify(server,null,2)+'\n');
const identities={};
for(const runtime of ['node','bun']){
 const frozen=await readFile(root+'/measured-exact-'+runtime+'.mjs');
 const current=await readFile('framework-comparison/participants/exact/dist-'+(runtime==='bun'?'bun-':'')+'server/'+(runtime==='bun'?'bun-':'')+'server-entry.js');
 assert.deepEqual(frozen,current);identities[runtime]=createHash('sha256').update(current).digest('hex');
}
await writeFile(prefix+'.json',JSON.stringify({commit,sourceSha256,sourceIdentity:'Uncommitted measured source; commit is the parent baseline',sourceState:await json(root+'/source-state.json'),sources,execution,connectionPreparation:'Separate gradual preparation controls; primary arrival charts retain abrupt growth',capacities,report,streamReport:{metadata:streamReport.metadata,server:streamReport.server},server,identities,validation:await json(root+'/verification.json'),runners:{measure:await readFile(root+'/run.mjs','utf8'),capacity:await readFile(root+'/capacity-runner.mjs','utf8'),publish:await readFile(import.meta.filename,'utf8')},previousReport:previous},null,2)+'\n');
console.log('Published complete SSR captures; browser evidence preserved.');
